// A single sales record generated by a producer thread
struct SalesRecord {
    int day;          // 1-30
    int month;        // 1-12
    int year;         // 16 (fixed)
    int store_id;     // 1 to p (one per producer)
    int register_num; // 1-6
    double amount;    // $0.50 - $999.99
    bool is_sentinel = false; // used by main to signal consumers to stop
};
